        let endParagraphInfo = this.owner.selection.getParagraphInfo(this.owner.selectionModule.end);
        const startIndex = this.owner.selection.getHierarchicalIndex(paragraphInfo.paragraph, paragraphInfo.offset.toString());
        const endIndex = this.owner.selection.getHierarchicalIndex(endParagraphInfo.paragraph, endParagraphInfo.offset.toString());
