const MOVE_TO = 'MT';
const SEGMENTS = 'Sgm';
const RECT = 'Rt';
const CLEAR_RECT = 'CR';
const FILL_RECT = 'FR';
const STROKE_RECT = 'SR';
const RESTORE = 'RES';
const SAVE = 'S';
const FILL_TEXT = 'FT';
const STROKE_TEXT = 'ST';
