/**
 * @private
 */
class CommentCharacterElementBox extends ElementBox {
    constructor(type) {
        super();
        this.commentType = 0;
        this.commentId = '';
        this.commentType = type;
    }
    get comment() {
        return this.commentInternal;
    }
    set comment(value) {
        this.commentInternal = value;
    }
    getLength() {
        return 1;
    }
    clone() {
        let comment = new CommentCharacterElementBox(this.commentType);
        comment.commentId = this.commentId;
        comment.commentType = this.commentType;
        if (!isNullOrUndefined(this.commentInternal)) {
            comment.commentInternal = this.commentInternal.clone();
        }
        return comment;
    }
    renderCommentMark(topPosition, leftPosition) {
        let documentHelper = this.line.paragraph.bodyWidget.page.documentHelper;
        let commentMarkDictionary = documentHelper.render.commentMarkDictionary;
        if (this.commentType === 0 && isNullOrUndefined(this.commentMark)) {
            this.commentMark = document.createElement('div');
            this.commentMark.style.display = 'none';
            this.commentMark.classList.add('e-de-cmt-mark');
            let span = document.createElement('span');
            span.classList.add('e-icons');
            span.classList.add('e-de-cmt-mark-icon');
            this.commentMarkSpan = span;
            this.commentMark.appendChild(span);
            if (documentHelper.owner.documentEditorSettings.commentSettings &&
                documentHelper.owner.documentEditorSettings.commentSettings.highlightCommentsByAuthor) {
                const firstCommentInLine = this.getFirstCommentInLine();
                const firstCommentAuthor = firstCommentInLine && firstCommentInLine.comment ? firstCommentInLine.comment.author : this.comment.author;
                const firstAuthorColor = documentHelper.getAuthorColor(firstCommentAuthor);
                this.commentMarkSpan.style.color = documentHelper.convertColorToRGBA(firstAuthorColor, 0.6);
                this.onCommentMarkMouseEnter = () => {
                    const firstComment = this.getFirstCommentInLine();
                    firstComment.updateCommentMarkColorOnHover();
                };
                this.onCommentMarkMouseLeave = () => {
                    const firstComment = this.getFirstCommentInLine();
                    firstComment.updateCommentMarkColorOnUnhover();
                };
                this.commentMarkSpan.addEventListener('mouseenter', this.onCommentMarkMouseEnter);
                this.commentMarkSpan.addEventListener('mouseleave', this.onCommentMarkMouseLeave);
            }
        }
        // RE-RENDER: Update color when highlight is enabled (handles editing cases with overlapping)
        if (documentHelper.owner.documentEditorSettings.commentSettings &&
            documentHelper.owner.documentEditorSettings.commentSettings.highlightCommentsByAuthor && this.commentType === 0 && this.commentMarkSpan && !isNullOrUndefined(this.commentMark)) {
            this.refreshCommentMarkAppearance(documentHelper, commentMarkDictionary);
        }
        if (this.line && isNullOrUndefined(this.commentMark.parentElement)) {
            documentHelper.pageContainer.appendChild(this.commentMark);
            this.commentMark.addEventListener('click', this.selectComment.bind(this));
        }
        let positionOverlap = false;
        let overlapKey;
        for (let index = 0; index < commentMarkDictionary.length; index++) {
            if (this.elementsOverlap(commentMarkDictionary.keys[index], topPosition, leftPosition)) {
                positionOverlap = true;
                overlapKey = commentMarkDictionary.keys[index];
                break;
            }
        }
        if (positionOverlap) {
            let ifNotPresent = true;
            for (let index = 0; index < commentMarkDictionary.get(overlapKey).length; index++) {
                if (commentMarkDictionary.get(overlapKey)[index] === this) {
                    ifNotPresent = false;
                    break;
                }
            }
            if (ifNotPresent) {
                commentMarkDictionary.get(overlapKey).push(this);
                // Hide this new overlapping span (only first span should be visible)
                if (documentHelper.owner.documentEditorSettings.commentSettings &&
                    documentHelper.owner.documentEditorSettings.commentSettings.highlightCommentsByAuthor && this.commentMarkSpan) {
                    this.commentMarkSpan.style.color = 'transparent';
                    this.commentMarkSpan.style.textShadow = '';
                }
            }
        }
        else {
            commentMarkDictionary.add(this.commentMark, [this]);
        }
        for (let index = 0; index < commentMarkDictionary.length; index++) {
            let element = commentMarkDictionary.keys[index];
            if (commentMarkDictionary.get(element).length == 1) {
                if (commentMarkDictionary.get(element)[0].commentMark) {
                    if (commentMarkDictionary.get(element)[0].commentMark.firstElementChild.classList.contains('e-de-multi-cmt-mark')) {
                        classList(commentMarkDictionary.get(element)[0].commentMark.firstElementChild, ['e-de-cmt-mark-icon'], ['e-de-multi-cmt-mark']);
                    }
                    else if (commentMarkDictionary.get(element)[0].commentInternal.isResolved && commentMarkDictionary.get(element)[0].commentMark.firstElementChild.classList.contains('e-de-cmt-mark-icon')) {
                        classList(commentMarkDictionary.get(element)[0].commentMark.
                            firstElementChild, ['e-de-cmt-resolve-icon'], ['e-de-cmt-mark-icon']);
                    }
                    else if (!commentMarkDictionary.get(element)[0].commentInternal.isResolved && commentMarkDictionary.get(element)[0].commentMark.firstElementChild.classList.contains('e-de-cmt-resolve-icon')) {
                        classList(commentMarkDictionary.get(element)[0].commentMark.firstElementChild, ['e-de-cmt-mark-icon'], ['e-de-cmt-resolve-icon']);
                    }
                }
            }
            if (commentMarkDictionary.get(element).length > 1) {
                for (let z = 0; z < commentMarkDictionary.get(element).length; z++) {
                    let resolve = true;
                    for (var z_1 = 0; z_1 < commentMarkDictionary.get(element).length; z_1++) {
                        if (commentMarkDictionary.get(element)[z_1].commentInternal && !commentMarkDictionary.get(element)[z_1].commentInternal.isResolved) {
                            resolve = false;
                            break;
                        }
                    }
                    if (commentMarkDictionary.get(element)[z].commentMark) {
                        if (commentMarkDictionary.get(element)[z].commentMark.firstElementChild.classList.contains('e-de-cmt-mark-icon')) {
                            classList(commentMarkDictionary.get(element)[z].commentMark.firstElementChild, ['e-de-multi-cmt-mark'], ['e-de-cmt-mark-icon']);
                        }
                        else if (!resolve && commentMarkDictionary.get(element)[z].commentMark.firstElementChild.classList.contains('e-de-multi-cmt-resolve')) {
                            classList(commentMarkDictionary.get(element)[z].commentMark.firstElementChild, ['e-de-multi-cmt-mark'], ['e-de-multi-cmt-resolve']);
                        }
                        else if (resolve) {
                            classList(commentMarkDictionary.get(element)[z].commentMark.firstElementChild, ['e-de-multi-cmt-resolve'], ['e-de-multi-cmt-mark']);
                        }
                    }
                }
            }
        }
    }
    elementsOverlap(elementOne, top, left) {
        const width = elementOne.offsetWidth;
        const height = elementOne.offsetHeight;
        const elementOneTop = parseFloat(elementOne.style.top);
        const elementOneLeft = parseFloat(elementOne.style.left);
        const elementOneBottom = elementOneTop + height;
        const elementOneRight = elementOneLeft + width;
        const elementTwoTop = parseFloat(top);
        const elementTwoLeft = parseFloat(left);
        const elementTwoBottom = elementTwoTop + height;
        const elementTwoRight = elementTwoLeft + width;
        return !(elementOneTop > elementTwoBottom ||
            elementOneRight < elementTwoLeft ||
            elementOneBottom < elementTwoTop ||
            elementOneLeft > elementTwoRight);
    }
    getFirstCommentInLine() {
        if (isNullOrUndefined(this.line) || isNullOrUndefined(this.line.children)) {
            return this;
        }
        for (let i = 0; i < this.line.children.length; i++) {
            const startComment = this.line.children[i];
            if (startComment instanceof CommentCharacterElementBox && startComment.commentType === 0) {
                return startComment;
            }
        }
        return this;
    }
    refreshCommentMarkAppearance(documentHelper, commentMarkDictionary) {
        const selectedComment = documentHelper.owner.documentHelper.currentSelectedComment;
        const firstCommentInLine = this.getFirstCommentInLine();
        const firstCommentAuthor = firstCommentInLine && firstCommentInLine.comment ? firstCommentInLine.comment.author : this.comment.author;
        const firstAuthorColor = documentHelper.getAuthorColor(firstCommentAuthor);
        // Get overlapping comments for this position
        const topPosition = this.commentMark.style.top;
        const leftPosition = this.commentMark.style.left;
        let overlapKey;
        let overlappingComments = [];
        for (let index = 0; index < commentMarkDictionary.length; index++) {
            if (this.elementsOverlap(commentMarkDictionary.keys[index], topPosition, leftPosition)) {
                overlapKey = commentMarkDictionary.keys[index];
                overlappingComments = commentMarkDictionary.get(overlapKey);
                break;
            }
        }
        if (overlappingComments.length > 1) {
            // Handle truly overlapping comments (multiple at same position)
            if (overlappingComments[0] === this) {
                // This is the first comment in overlapping group
                let isAnyCommentInGroupSelected = false;
                // Check if selectedComment is ANY of the overlapping comments
                if (selectedComment) {
                    for (let i = 0; i < overlappingComments.length; i++) {
                        if (overlappingComments[i].comment === selectedComment) {
                            isAnyCommentInGroupSelected = true;
                            break;
                        }
                    }
                }
                if (isAnyCommentInGroupSelected) {
                    // ANY comment in this group is selected: show selected author color + textShadow
                    const selectedAuthorColor = documentHelper.getAuthorColor(selectedComment.author);
                    this.commentMarkSpan.style.color = selectedAuthorColor;
                    this.commentMarkSpan.style.textShadow = `0 0 2px ${selectedAuthorColor}`;
                }
                else {
                    // No selection in group: show first comment color with reduced opacity, reset textShadow
                    this.commentMarkSpan.style.color = documentHelper.convertColorToRGBA(firstAuthorColor, 0.6);
                    this.commentMarkSpan.style.textShadow = '';
                }
            }
            else {
                // Not the first comment (overlapping): hide and reset textShadow
                this.commentMarkSpan.style.color = 'transparent';
                this.commentMarkSpan.style.textShadow = '';
            }
        }
        else {
            // Single comment (not overlapping): check standard selection state
            const isMarkSelected = this.commentMark.classList.contains('e-de-cmt-mark-selected');
            if (isMarkSelected && selectedComment && selectedComment === this.comment) {
                // Selected state: use full opacity color + textShadow
                const selectedAuthorColor = documentHelper.getAuthorColor(selectedComment.author);
                this.commentMarkSpan.style.color = selectedAuthorColor;
                this.commentMarkSpan.style.textShadow = `0 0 2px ${selectedAuthorColor}`;
            }
            else {
                // Unselected state: use opacity color, reset textShadow
                this.commentMarkSpan.style.color = documentHelper.convertColorToRGBA(firstAuthorColor, 0.6);
                this.commentMarkSpan.style.textShadow = '';
            }
        }
    }
    /**
     * @private
     * Helper method to update comment mark colors on hover/enter state
     * Applies full opacity color with textShadow enhancement
     */
    updateCommentMarkColorOnHover() {
        const documentHelper = this.line.paragraph.bodyWidget.page.documentHelper;
        const commentMarkDictionary = documentHelper.render.commentMarkDictionary;
        const overlappedComments = commentMarkDictionary.get(this.commentMark);
        if (!overlappedComments || overlappedComments.length === 0) {
            return;
        }
        const firstCommentInLine = overlappedComments[0];
        const selectedComment = documentHelper.owner.documentHelper.currentSelectedComment;
        const firstAuthorColor = documentHelper.getAuthorColor(firstCommentInLine.comment.author);
        // Determine hover color: use selected comment's color if selected, otherwise first comment's color
        let hoverColor = firstAuthorColor;
        if (selectedComment) {
            const selectedFirstCommentElement = selectedComment.commentStart.getFirstCommentInLine();
            if (selectedFirstCommentElement && selectedFirstCommentElement.comment === firstCommentInLine.comment) {
                hoverColor = documentHelper.getAuthorColor(selectedComment.author);
            }
        }
        // Show only first span with hover color + textShadow
        if (overlappedComments[0] && overlappedComments[0].commentMarkSpan) {
            overlappedComments[0].commentMarkSpan.style.color = hoverColor;
            overlappedComments[0].commentMarkSpan.style.textShadow = `0 0 2px ${hoverColor}`;
        }
        // Hide other overlapping spans and reset textShadow
        for (let i = 1; i < overlappedComments.length; i++) {
            const overlappedStart = overlappedComments[i];
            if (overlappedStart && overlappedStart.commentMarkSpan) {
                overlappedStart.commentMarkSpan.style.color = 'transparent';
                overlappedStart.commentMarkSpan.style.textShadow = '';
            }
        }
    }
    /**
     * @private
     * Helper method to update comment mark colors on unhover/leave state
     * Applies selected comment color with textShadow if selected, else reduced opacity without textShadow
     */
    updateCommentMarkColorOnUnhover() {
        const documentHelper = this.line.paragraph.bodyWidget.page.documentHelper;
        const commentMarkDictionary = documentHelper.render.commentMarkDictionary;
        const overlappedComments = commentMarkDictionary.get(this.commentMark);
        if (!overlappedComments || overlappedComments.length === 0) {
            return;
        }
        const firstCommentInLine = overlappedComments[0];
        const selectedComment = documentHelper.owner.documentHelper.currentSelectedComment;
        const firstAuthorColor = documentHelper.getAuthorColor(firstCommentInLine.comment.author);
        let isAnyCommentOnLineSelected = false;
        if (selectedComment) {
            const selectedFirstCommentElement = selectedComment.commentStart.getFirstCommentInLine();
            const selectedFirstComment = selectedFirstCommentElement ? selectedFirstCommentElement.comment : null;
            isAnyCommentOnLineSelected = (selectedFirstComment === firstCommentInLine.comment);
        }
        // Show only first span with appropriate color + textShadow if still selected
        if (overlappedComments[0] && overlappedComments[0].commentMarkSpan) {
            if (isAnyCommentOnLineSelected) {
                const selectedAuthorColor = documentHelper.getAuthorColor(selectedComment.author);
                overlappedComments[0].commentMarkSpan.style.color = selectedAuthorColor;
                overlappedComments[0].commentMarkSpan.style.textShadow = `0 0 2px ${selectedAuthorColor}`;
            }
            else {
                overlappedComments[0].commentMarkSpan.style.color = documentHelper.convertColorToRGBA(firstAuthorColor, 0.6);
                overlappedComments[0].commentMarkSpan.style.textShadow = '';
            }
        }
        // Hide other overlapping spans and reset textShadow
        for (let i = 1; i < overlappedComments.length; i++) {
            const overlappedStart = overlappedComments[i];
            if (overlappedStart && overlappedStart.commentMarkSpan) {
                overlappedStart.commentMarkSpan.style.color = 'transparent';
                overlappedStart.commentMarkSpan.style.textShadow = '';
            }
        }
    }
    selectComment() {
        let documentHelper = this.line.paragraph.bodyWidget.page.documentHelper;
        let commentMarkDictionary = documentHelper.render.commentMarkDictionary;
        let topPosition = this.commentMark.style.top;
        let leftPosition = this.commentMark.style.left;
        let currentIndex = 0;
        let navigationArray = [];
        for (let index = 0; index < commentMarkDictionary.keys.length; index++) {
            if (this.elementsOverlap(commentMarkDictionary.keys[index], topPosition, leftPosition)) {
                navigationArray = commentMarkDictionary.get(commentMarkDictionary.keys[index]);
                break;
            }
        }
        if (!documentHelper.owner.documentHelper.currentSelectedComment) {
            currentIndex = 0;
        }
        else {
            for (let index = 0; index < navigationArray.length; index++) {
                if (navigationArray[index].comment === documentHelper.owner.documentHelper.currentSelectedComment) {
                    currentIndex = index;
                    break;
                }
            }
            if (currentIndex < (navigationArray.length - 1)) {
                currentIndex += 1;
            }
            else {
                currentIndex = 0;
            }
        }
        if (documentHelper.owner) {
            if (!documentHelper.owner.commentReviewPane.commentPane.isEditMode) {
                documentHelper.selectComment(navigationArray[currentIndex].comment);
            }
            else {
                documentHelper.owner.showComments = true;
            }
        }
    }
    removeCommentMark() {
        if (this.commentMark && this.commentMark.parentElement) {
            this.commentMark.removeEventListener('click', this.selectComment.bind(this));
            this.commentMark.parentElement.removeChild(this.commentMark);
        }
    }
    destroy() {
        if (this.commentMarkSpan) {
            if (this.onCommentMarkMouseEnter) {
                this.commentMarkSpan.removeEventListener('mouseenter', this.onCommentMarkMouseEnter);
            }
            if (this.onCommentMarkMouseLeave) {
                this.commentMarkSpan.removeEventListener('mouseleave', this.onCommentMarkMouseLeave);
            }
        }
        if (this.commentMark) {
            this.removeCommentMark();
        }
        this.commentMark = undefined;
        this.commentInternal = undefined;
        this.commentId = undefined;
        super.componentDestroy();
    }
}
