            const selectionStartParagraph = this.owner.selectionModule.start.paragraph;
            let selectionStartIndex = 0;
            const selectionStartInlineObj = selectionStartParagraph.getInline(this.owner.selectionModule.start.offset, selectionStartIndex);
            const selectionStartInline = selectionStartInlineObj.element;
            selectionStartIndex = selectionStartInlineObj.index;
