    /**
     * @private
     * @param fieldStart
     * @returns {void}
     */
    selectContentControlInternal(fieldStart) {
        if (fieldStart) {
            const offset = fieldStart.nextElement instanceof EditRangeStartElementBox ?
                fieldStart.line.getOffset(fieldStart, 2) : fieldStart.line.getOffset(fieldStart, 1);
            const startPosition = new TextPosition(this.owner);
            let fieldEnd = fieldStart.reference;
            startPosition.setPositionParagraph(fieldStart.line, offset);
            const endoffset = fieldEnd.previousElement instanceof EditRangeEndElementBox ?
                fieldEnd.line.getOffset(fieldEnd, -1) : fieldEnd.line.getOffset(fieldEnd, 0);
            const endPosition = new TextPosition(this.owner);
            endPosition.setPositionParagraph(fieldEnd.line, endoffset);
            //selects the field range
            this.documentHelper.selection.selectRange(startPosition, endPosition);
        }
    }
    /**
     * @private
     * @param fieldStart
     * @returns {void}
     */
    selectFieldInternal(fieldStart, isKeyBoardEvent, isReplacingFormResult) {
        if (fieldStart) {
            const formFillingMode = this.documentHelper.isFormFillProtectedMode || isReplacingFormResult;
            let fieldEnd = fieldStart.fieldEnd;
            if (formFillingMode) {
                fieldStart = fieldStart.fieldSeparator;
            }
            const offset = fieldStart.line.getOffset(fieldStart, formFillingMode ? 1 : 0);
            const startPosition = new TextPosition(this.owner);
            startPosition.setPositionParagraph(fieldStart.line, offset);
            const isBookmark = fieldStart.nextNode instanceof BookmarkElementBox;
            if (isBookmark && !formFillingMode && fieldStart.nextElement.reference) {
                fieldEnd = fieldStart.nextElement.reference;
            }
            const endoffset = fieldEnd.line.getOffset(fieldEnd, formFillingMode ? 0 : 1);
            const endPosition = new TextPosition(this.owner);
            endPosition.setPositionParagraph(fieldEnd.line, endoffset);
            //selects the field range
            this.documentHelper.selection.selectRange(startPosition, endPosition);
            if (!isReplacingFormResult) {
                this.triggerFormFillEvent(isKeyBoardEvent);
            }
        }
    }
    /**
     * @private
     * @param contentControl
     * @returns {void}
     */
    selectContentControl(contentControl) {
        if (contentControl) {
            let fieldEnd = contentControl.reference;
            const offset = contentControl.line.getOffset(contentControl, 0);
            const startPosition = new TextPosition(this.owner);
            startPosition.setPositionParagraph(contentControl.line, offset);
            const endoffset = fieldEnd.line.getOffset(fieldEnd, 1);
            const endPosition = new TextPosition(this.owner);
            endPosition.setPositionParagraph(fieldEnd.line, endoffset);
            this.documentHelper.selection.selectRange(startPosition, endPosition);
        }
    }
    /**
     * @param shape
     * @private
     * @returns {void}
     */
    selectShape(shape) {
        if (shape) {
            const offset = shape.line.getOffset(shape, 0);
            const startPosition = new TextPosition(this.owner);
            startPosition.setPositionParagraph(shape.line, offset);
            const endoffset = shape.line.getOffset(shape, 1);
            const endPosition = new TextPosition(this.owner);
            endPosition.setPositionParagraph(shape.line, endoffset);
            this.documentHelper.selection.selectRange(startPosition, endPosition);
        }
    }
