    isContentControlInSelection(paragraph) {
        const contentControls = this.owner.documentHelper.contentControlCollection;
        if (isNullOrUndefined(contentControls) || contentControls.length === 0) {
            return false;
        }
        const child = paragraph.childWidgets[0];
        if (!child.children || child.children.length === 0) {
            return false;
        }
        for (let i = 0; i < child.children.length; i++) {
            const element = child.children[i];
            if (element instanceof ContentControl) {
                const contentControlStart = element;
                const contentControlEnd = contentControlStart.reference;
                if (!isNullOrUndefined(contentControlStart) && !isNullOrUndefined(contentControlEnd)) {
                    if (this.owner.selection.isElementInSelection(contentControlStart, false)
                        && this.owner.selection.isElementInSelection(contentControlEnd, true)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
