    /**
     * Gets the entire document's comment information.
     *
     * @returns {CommentInfo[]} Returns the collection of comments.
     */
    getComments() {
        const data = [];
        const commentCollection = this.documentHelper.comments;
        if (commentCollection.length > 0) {
            let tempData = [];
            for (const comment of this.documentHelper.comments) {
                tempData = [];
                const commentProperties = {
                    author: comment.author,
                    isResolved: comment.isResolved ? comment.isResolved : false,
                    dateTime: this.editor.parseDateTime(comment.createdDate)
                };
                for (const replyComment of comment.replyComments) {
                    const replyCommentProperties = {
                        author: replyComment.author,
                        isResolved: replyComment.isResolved ? comment.isResolved : false,
                        dateTime: this.editor.parseDateTime(replyComment.createdDate)
                    };
                    const commentText = HelperMethods.parseCommentAsText(replyComment);
                    const newComment = new Comment(replyComment.commentId, replyCommentProperties, commentText);
                    tempData.push(newComment);
                }
                const commentInfo = {
                    id: comment.commentId,
                    text: HelperMethods.parseCommentAsText(comment),
                    commentProperties: commentProperties,
                    replies: tempData
                };
                data.push(commentInfo);
            }
        }
        return data;
    }
    /**
     * Regenerates comment highlight colors when highlightCommentsByAuthor setting is toggled.
     *
     * @returns {void}
     * @private
     */
    regenerateCommentHighlights() {
        const helper = this.documentHelper;
        const commentMarkDictionary = helper.render.commentMarkDictionary;
        const highlightEnabled = this.documentEditorSettings.commentSettings &&
            this.documentEditorSettings.commentSettings.highlightCommentsByAuthor;
        // Iterate through all comment marks and call renderCommentMark for re-render color logic
        for (const markElement of commentMarkDictionary.keys) {
            const overlappingComments = commentMarkDictionary.get(markElement);
            if (!overlappingComments || overlappingComments.length === 0) {
                continue;
            }
            // Handle event listeners and trigger re-render color update for all overlapping comments
            for (let i = 0; i < overlappingComments.length; i++) {
                const comment = overlappingComments[parseInt(i.toString(), 10)];
                if (comment && comment.commentMarkSpan) {
                    if (!highlightEnabled) {
                        // Unwire events when highlighting is disabled
                        if (comment.onCommentMarkMouseEnter) {
                            comment.commentMarkSpan.removeEventListener('mouseenter', comment.onCommentMarkMouseEnter);
                        }
                        if (comment.onCommentMarkMouseLeave) {
                            comment.commentMarkSpan.removeEventListener('mouseleave', comment.onCommentMarkMouseLeave);
                        }
                        // Clear color and textShadow when highlight disabled
                        comment.commentMarkSpan.style.color = '';
                        comment.commentMarkSpan.style.textShadow = '';
                    }
                    else {
                        // Wire events when highlighting is enabled
                        if (comment.onCommentMarkMouseEnter) {
                            comment.commentMarkSpan.addEventListener('mouseenter', comment.onCommentMarkMouseEnter);
                        }
                        if (comment.onCommentMarkMouseLeave) {
                            comment.commentMarkSpan.addEventListener('mouseleave', comment.onCommentMarkMouseLeave);
                        }
                    }
                }
            }
        }
        if (!isNullOrUndefined(this.commentReviewPane) || !isNullOrUndefined(this.commentReviewPane.commentPane)) {
            const commentPane = this.commentReviewPane.commentPane;
            // Iterate through all comment nodes in the pane to update pane borders
            const commentKeys = commentPane.comments.keys;
            for (const comment of commentKeys) {
                const commentView = commentPane.comments.get(comment);
                if (!commentView || !commentView.parentElement) {
                    continue;
                }
                const isSelected = commentView.parentElement.classList.contains('e-de-cmt-selection');
                if (highlightEnabled) {
                    // Highlight enabled: show colors for selected/hovered states
                    if (isSelected) {
                        // Selected state: use comment's author color
                        const authorColor = helper.getAuthorColor(comment.author);
                        commentView.parentElement.style.borderLeftColor = authorColor;
                    }
                    else {
                        // Unselected state: clear border (will be set on hover)
                        commentView.parentElement.style.borderLeftColor = '';
                    }
                }
                else {
                    // Highlight disabled: clear all border colors
                    commentView.parentElement.style.borderLeftColor = '';
                }
            }
        }
        this.viewer.updateScrollBars();
    }
