        const toolbarWrapper = createElement('div', { className: 'e-de-tlbr-wrapper' });
        const toolbarTarget = createElement('div', { className: 'e-de-toolbar' });
        this.initToolbarItems();
        toolbarWrapper.appendChild(toolbarTarget);
        toolbarContainer.appendChild(toolbarWrapper);
        // Show hide pane button initialization
        const locale = this.container.localObj;
        const propertiesPaneDiv = createElement('div', { className: 'e-de-ctnr-properties-pane-btn' });
